questionvariables.text:
f: 3$ SA: rand_with_step(1.2*f, 3.9*f, 0.1)$ AB: 1.5$ xF: -f$ xC: -2*f$ xA: -SA$ xAp: xF*xA/(xA-xF)$ gam: -(xAp/xA)$ ABp: gam*AB$ 
m1e: -AB/xF$ p1e: AB$ m2e: -AB/(xC-xA)$ p2e: -m2e*xC$ m3e: 0$ p3e: AB*xF/(xF-xA)$ m4e: -AB/xA$ p4e: 0$ 
m3i: -AB/(xF-xA)$ p3i: -m3i*xF$ m4i: AB/xA$ 
xmin: -8$ xmax: 8$ xtol: 0.5$ 
/* Construction dynamique du TANS via des listes Maxima pures */
ray1_inc: [xA, 0, 1]$ ray1_ref: [xmin, 0, 1]$ ray2_full: [xmin, xmax, 1]$ ray3_inc: [xA, 0, 1]$ ray3_ref: [xmin, 0, 1]$ ray4_inc: [xA, 0, 1]$ ray4_ref: [xmin, 0, 1]$ abp_piece: [0, ABp, 1]$ 
ray1: [0, AB, [ray1_inc]]$ ray2: [m2e, p2e, [ray2_full]]$ ray3i: [m3i, p3i, [ray3_inc]]$ ray3e: [0, p3e, [ray3_ref]]$ ray4i: [m4i, 0, [ray4_inc]]$ ray4e: [m4e, 0, [ray4_ref]]$ ray1e: [m1e, p1e, [ray1_ref]]$ abp: ["vert", xAp, [abp_piece]]$ 
rayList_ans: [ray1, ray1e, ray2, ray3i, ray3e, ray4i, ray4e, abp]$ ptList_ans: [["B'", xAp, ABp], ["A'", xAp, 0]]$ 
TANS: miroir_construction(rayList_ans, ptList_ans)$ 
found_ray(rayList, mExp, pExp, mtol, ptol) := block([simp, found, r],
  simp: true,
  found: false,
  for r in rayList do (
    if listp(r) and length(r) >= 2 and numberp(r[1]) and numberp(r[2]) then (
      if abs(r[1] - mExp) < mtol and abs(r[2] - pExp) < ptol then found: true
    )
  ),
  found
)$ 
found_point(ptList, xExp, yExp, tol) := block([simp, found, p],
  simp: true,
  found: false,
  for p in ptList do (
    if listp(p) and length(p) = 3 and numberp(p[2]) and numberp(p[3]) then (
      if abs(p[2] - xExp) < tol and abs(p[3] - yExp) < tol then found: true
    )
  ),
  found
)$ 
all_pieces_status(pieces, want) := block([simp, ok, pc],
  simp: true,
  ok: true,
  for pc in pieces do (
    if not (listp(pc) and length(pc) >= 3 and is(pc[3] = want)) then ok: false
  ),
  ok
)$ 
found_ray_status(rayList, mExp, pExp, mtol, ptol, want) := block([simp, found, r],
  simp: true,
  found: false,
  for r in rayList do (
    if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) and length(r[3]) > 0 then (
      if abs(r[1] - mExp) < mtol and abs(r[2] - pExp) < ptol and all_pieces_status(r[3], want) then found: true
    )
  ),
  found
)$ 
line_pieces(rayList, m, p, mtol, ptol) := block([simp, result, r],
  simp: true,
  result: [],
  for r in rayList do (
    if listp(r) and length(r) >= 3 and numberp(r[1]) and numberp(r[2]) and listp(r[3]) then (
      if abs(r[1] - m) < mtol and abs(r[2] - p) < mtol then result: append(result, r[3])
    )
  ),
  result
)$ 
status_covering_x(pieces, x, tol) := block([simp, pc, lo, hi, found],
  simp: true,
  found: -1,
  for pc in pieces do (
    if listp(pc) and length(pc) >= 3 then (
      lo: min(pc[1], pc[2]),
      hi: max(pc[1], pc[2]),
      if x >= lo - tol and x <= hi + tol then found: pc[3]
    )
  ),
  found
)$ 
seg_required_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want) := block([simp, pieces, s1, s2],
  simp: true,
  pieces: line_pieces(rayList, m, p, mtol, ptol),
  s1: status_covering_x(pieces, xlo + tol, tol),
  s2: status_covering_x(pieces, xhi - tol, tol),
  is(s1 = want) and is(s2 = want)
)$ 
seg_absent(rayList, m, p, mtol, ptol, xlo, xhi, tol) := block([simp, pieces, s1],
  simp: true,
  pieces: line_pieces(rayList, m, p, mtol, ptol),
  s1: status_covering_x(pieces, (xlo + xhi) / 2, tol),
  is(s1 = -1)
)$ 
seg_optional_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want) := block([simp],
  simp: true,
  seg_absent(rayList, m, p, mtol, ptol, xlo, xhi, tol) or seg_required_status(rayList, m, p, mtol, ptol, xlo, xhi, tol, want)
)$ 
found_AB_status(rayList, xExp, y1Exp, y2Exp, xtol, ytol, want) := block([simp, found, r, pc, ylo, yhi, plo, phi],
  simp: true,
  found: false,
  ylo: min(y1Exp, y2Exp),
  yhi: max(y1Exp, y2Exp),
  for r in rayList do (
    if listp(r) and length(r) = 3 and stringp(r[1]) and is(r[1] = "vert") and numberp(r[2])
       and abs(r[2] - xExp) < xtol and listp(r[3]) then (
      for pc in r[3] do (
        if listp(pc) and length(pc) >= 3 then (
          plo: min(pc[1], pc[2]),
          phi: max(pc[1], pc[2]),
          if abs(plo - ylo) < ytol and abs(phi - yhi) < ytol and is(pc[3] = want) then found: true
        )
      )
    )
  ),
  found
)$ 
require_mc(mc) := block(
  if not is(safe_op(mc) = "miroir_construction") or not is(length(mc) = 2) then
    "La réponse doit être générée par la construction graphique ci-dessus (fonction miroir_construction(rayons, points))."
  else
    true
)$ 
ans1_validator(ex) := stack_seq_validator(ex, [require_mc])$
